use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n = cs.len()
    if n == 0 { return false }
    let start = if cs[0] == '-' { 1 } else { 0 }
    if start >= n { return false }
    let mut i = start
    while i < n {
        if cs[i] < '0' || cs[i] > '9' { return false }
        i += 1
    }
    true
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split_whitespace() {
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 { return "error: underflow" }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" { st.push(a + b) }
            else if t == "-" { st.push(a - b) }
            else if t == "*" { st.push(a * b) }
            else {
                if b == 0 { return "error: divzero" }
                st.push(a / b)
            }
        } else if is_int(t) {
            match t.parse::<int>() {
                Ok(v) => st.push(v),
                Err(_) => return "error: token",
            }
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 { return "error: leftover" }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(eval(line))
    }
}

